/**
 * Nemons Candidate Generation — from Experience
 *
 * The CandidateGenerator bridges Stage D (Experience) and Stage F
 * (Governed Evolution): it produces a candidate change to an
 * operational asset based on what was learned from a verified-succeeded
 * Run's Experience.
 *
 * Architectural principles enforced here:
 *   - "A candidate change must not become approved merely because it
 *     was generated by a successful Run." — the generator produces a
 *     CANDIDATE (status=proposed); approval requires governed review.
 *   - "No silent mutation" — the generator does NOT modify any asset
 *     directly; it produces a candidate that goes through the
 *     GovernedEvolutionEngine.
 *   - "Use is not adoption" — the generated candidate is `proposed`,
 *     NOT `approved`. Using it in a Run requires the candidate to be
 *     reviewed and promoted (just like any other candidate).
 *   - "Evidence before claims" — the generator requires the source
 *     Experience to be `approved` (governed) before it can produce
 *     a candidate. An `observed` Experience does NOT produce candidates.
 *
 * This is the architectural link that completes the chain:
 *   Run → Evidence → Evaluation → Experience → Candidate → Governed Evolution
 *
 * NOTE: The generator produces candidates for ANY asset kind (skill,
 * persona, knowledge, memory). The caller decides what content to
 * propose; the generator handles the lifecycle wiring.
 */

import type { CandidateRecord, CandidateAssetKind, CandidateChangeKind } from "../schemas/candidate.js";
import type { Experience } from "../schemas/experience.js";
import type { CandidateId } from "../core/identifiers.js";
import { asCandidateId, freshId } from "../core/identifiers.js";
import { ContractValidationError, LifecycleViolationError } from "../core/errors.js";
import type { Provenance, ProvenanceSource } from "../core/provenance.js";

/**
 * The kind of candidate the generator should produce.
 *
 * - `create_from_experience` — propose a NEW asset whose content is
 *   derived from the Experience's summary + content.
 * - `update_from_experience` — propose an UPDATE to an existing asset
 *   whose content is derived from the Experience.
 *
 * The caller provides the asset id for updates; for creates, the
 * generator mints a new asset id.
 */
export type CandidateGenerationKind = "create_from_experience" | "update_from_experience";

/**
 * Inputs to generate a candidate from an Experience.
 */
export interface GenerateFromExperienceInput {
  /**
   * The source Experience. MUST be `approved` (the generator refuses
   * to produce candidates from non-approved Experiences — encodes
   * "Evidence before claims" at the candidate-generation level).
   */
  readonly experience: Experience;

  /**
   * The kind of candidate to generate.
   */
  readonly generationKind: CandidateGenerationKind;

  /**
   * The kind of asset the candidate targets.
   */
  readonly assetKind: CandidateAssetKind;

  /**
   * The asset id (for updates) or undefined (for creates — the
   * generator mints a new id).
   */
  readonly assetId?: string;

  /**
   * The proposed new version for the asset.
   */
  readonly proposedVersion: string;

  /**
   * The proposed new content for the asset. The generator wraps this
   * in a CandidateRecord; the content is the caller's responsibility.
   */
  readonly content: Readonly<Record<string, unknown>>;

  /**
   * The actor who proposed this candidate (recorded as proposedBy).
   * Defaults to the system identifier "nemons.candidate-generator".
   */
  readonly proposedBy?: string;

  /**
   * The rationale for the candidate. Defaults to a generated
   * rationale that references the source Experience.
   */
  readonly rationale?: string;

  /**
   * For updates: the candidate id this one supersedes. The generator
   * verifies the superseded candidate exists and is `approved`.
   */
  readonly supersedesCandidateId?: CandidateId;

  /**
   * For updates: the version being superseded.
   */
  readonly supersedesVersion?: string;
}

/**
 * The result of generating a candidate from an Experience.
 */
export interface GeneratedCandidate {
  /**
   * The generated CandidateRecord (status=proposed).
   */
  readonly candidate: CandidateRecord;

  /**
   * The id of the source Experience (preserves traceability).
   */
  readonly sourceExperienceId: string;

  /**
   * The id of the source Run (preserves traceability).
   */
  readonly sourceRunId: string;
}

/**
 * The CandidateGenerator interface.
 */
export interface CandidateGenerator {
  /**
   * Generates a CandidateRecord from an approved Experience. The
   * candidate starts as `proposed`; approval requires governed review.
   *
   * Throws if the Experience is NOT `approved` (encodes "Evidence
   * before claims").
   * Throws if the generationKind is `update_from_experience` but no
   * `assetId` is provided.
   */
  generateFromExperience(input: GenerateFromExperienceInput): GeneratedCandidate;
}

/**
 * Default CandidateGenerator implementation.
 *
 * The generator:
 *   1. Verifies the source Experience is `approved`.
 *   2. Verifies the input consistency (update requires assetId).
 *   3. Mints a new CandidateId.
 *   4. Constructs the CandidateRecord with:
 *      - status: "proposed" (NEVER approved — the generator does NOT
 *        bypass governed review)
 *      - provenance: observed (initial — must be promoted via review)
 *      - proposedBy: defaults to "nemons.candidate-generator"
 *      - rationale: defaults to a reference to the source Experience
 *      - evidenceRefs: references the source Experience's id (so the
 *        candidate is traceable to its source)
 *      - changeKind: "create" for creates, "update" for updates
 *      - supersedesCandidateId: as provided by the caller
 *
 * The generator does NOT add the candidate to the store; the caller
 * passes the candidate to the GovernedEvolutionEngine.propose() for
 * storage + lifecycle management.
 */
export class DefaultCandidateGenerator implements CandidateGenerator {
  generateFromExperience(input: GenerateFromExperienceInput): GeneratedCandidate {
    const { experience } = input;

    // 1. Verify the Experience is approved
    if (experience.provenance.kind !== "approved") {
      throw new LifecycleViolationError(
        `Cannot generate candidate from Experience: provenance kind is ${experience.provenance.kind} (must be 'approved'). ` +
          `Only approved Experiences can generate candidates — encodes "Evidence before claims" at the candidate-generation level.`,
        {
          details: {
            experienceId: experience.id,
            provenanceKind: experience.provenance.kind,
          },
        },
      );
    }

    // 2. Verify input consistency for updates
    if (input.generationKind === "update_from_experience") {
      if (input.assetId === undefined) {
        throw new ContractValidationError(
          "Cannot generate update candidate: assetId is required for update_from_experience generation kind.",
          { details: { generationKind: input.generationKind } },
        );
      }
      // If supersedesCandidateId is set, the caller has explicitly
      // chosen to supersede a previous candidate. If not set, the
      // generator still allows the update — the engine will handle
      // the supersede chain at propose() time (though it will reject
      // the candidate if no supersedesCandidateId is set for a
      // non-create changeKind, per the engine's rules).
    }

    // 3. Mint a new CandidateId
    const id: CandidateId = asCandidateId(freshId());
    const nowIso = new Date().toISOString();

    // 4. Build the provenance: observed-kind (initial), human source
    const proposedBy = input.proposedBy ?? "nemons.candidate-generator";
    const source: ProvenanceSource = {
      kind: "human",
      actor: proposedBy,
      at: nowIso,
    };
    const provenance: Provenance = {
      kind: "observed",
      source,
    };

    // 5. Build the rationale (default references the source Experience)
    const rationale =
      input.rationale ??
      `Generated from Experience ${experience.id} (Run ${experience.runId}): ${experience.summary}`;

    // 6. Build the evidenceRefs (reference the source Experience)
    const evidenceRefs = [experience.id];

    // 7. Determine the changeKind
    const changeKind: CandidateChangeKind =
      input.generationKind === "create_from_experience" ? "create" : "update";

    // 8. Mint an assetId for creates
    const assetId = input.assetId ?? `asset-${freshId().slice(0, 8)}`;

    // 9. Construct the candidate
    const candidate: CandidateRecord = {
      id,
      assetKind: input.assetKind,
      assetId,
      proposedVersion: input.proposedVersion,
      changeKind,
      content: input.content,
      provenance,
      status: "proposed", // CRITICAL: NEVER approved — bypasses nothing
      proposedBy,
      proposedAt: nowIso,
      rationale,
      evidenceRefs,
      reviewTrail: [],
      supersedesCandidateId: input.supersedesCandidateId,
      supersedesVersion: input.supersedesVersion,
    };

    return {
      candidate,
      sourceExperienceId: experience.id,
      sourceRunId: experience.runId,
    };
  }
}
